use crate::api::client::ApiClient;
use crate::models::ResultWithDefaultError;
use crate::utilities;
use std::collections::HashMap;
use std::io::{self, Write};

const ROUNDING_SECONDS: i64 = 15 * 60;
const MINIMUM_SECONDS: i64 = 30 * 60;

pub struct InvoiceCommand;

fn billable_seconds(duration: i64) -> i64 {
    let rounded = ((duration + ROUNDING_SECONDS - 1) / ROUNDING_SECONDS) * ROUNDING_SECONDS;
    rounded.max(MINIMUM_SECONDS)
}

impl InvoiceCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
    ) -> ResultWithDefaultError<()> {
        let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
        let entries = api_client.get_time_entries_filtered(since, until).await?;
        let mut totals = HashMap::<String, i64>::new();

        for entry in entries {
            if entry.billable && entry.stop.is_some() && entry.duration >= 0 {
                let project = entry
                    .project
                    .map(|project| project.name)
                    .unwrap_or_else(|| "No Project".to_string());
                *totals.entry(project).or_default() += billable_seconds(entry.duration);
            }
        }

        let mut totals: Vec<_> = totals.into_iter().collect();
        totals.sort_by(|(left_name, left_seconds), (right_name, right_seconds)| {
            right_seconds
                .cmp(left_seconds)
                .then_with(|| left_name.cmp(right_name))
        });

        let mut stdout = io::BufWriter::new(io::stdout().lock());
        if totals.is_empty() {
            writeln!(stdout, "(no data)").expect("failed to print invoice");
            return Ok(());
        }

        let total_seconds: i64 = totals.iter().map(|(_, seconds)| seconds).sum();
        for (project, seconds) in totals {
            writeln!(stdout, "{seconds}s  {project}").expect("failed to print invoice");
        }
        writeln!(stdout, "{total_seconds}s  Total").expect("failed to print invoice");
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::{billable_seconds, MINIMUM_SECONDS};

    #[test]
    fn rounds_each_entry_then_applies_minimum() {
        assert_eq!(billable_seconds(1), MINIMUM_SECONDS);
        assert_eq!(billable_seconds(15 * 60), MINIMUM_SECONDS);
        assert_eq!(billable_seconds(15 * 60 + 1), 30 * 60);
        assert_eq!(billable_seconds(30 * 60), 30 * 60);
        assert_eq!(billable_seconds(30 * 60 + 1), 45 * 60);
    }
}

